/**
 * A claim a person makes on a sheet: an amount (two decimals), a date, a note and a status. A negative amount is a
 * correction of the settled claim of the same person whose number it names.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /**
     * The number given when the claim is opened: the sheet's next (1, 2, ...), or while the sheet numbers by period
     * its period's next (P1-1, X-1 for no period); kept when it is voided, never reused; null for a claim never
     * opened.
     */
    @Column(name = "claim_number")
    private String number;

    /** The sequence a period-numbered claim was counted in: its period's name, or X; null otherwise. */
    @Column(name = "number_sequence")
    private String numberSequence;

    /** The claim's place in its number sequence; null unless period-numbered. */
    @Column(name = "number_in_sequence")
    private Long numberInSequence;

    /** The due fixed when the claim was settled; null while it is live. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; null for a claim never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user whose open editor holds the claim, so no one else may edit it; null while none does. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether the claim is bound by its person's last statement. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim is bound to by its person's last statement; null for n/a or when not stated. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the settled claim a correction corrects; null for a claim that is not a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The number of the claim this one was split off; null for a claim not split off another. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The date the claim's rounding follows: its own date, or for a correction the date of the claim it corrects. */
    @Column(name = "rounds_on", nullable = false)
    private LocalDate roundsOn;

    /**
     * The date the claim is due by: fixed when it is added, from the terms in force for its person's grade on its
     * date; later changes to the terms or to its date leave it as it is.
     */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /**
     * The date the claim is deferred until; null for one never deferred. While the sheet's today is before it an
     * OPEN claim is deferred (see {@link #isDeferredOn}).
     */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The sheet's today when the claim was deferred; null for one never deferred, or before that was kept. */
    @Column(name = "deferred_on")
    private LocalDate deferredOn;

    /** Whether the claim was added while its period was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** How many proofs the claim has; raised by one at a time. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /**
     * The claim's place in the list, newest first: the next place when it is added or moved to another person. The
     * store gives it; a move takes the next through {@link ClaimRepository#relist}.
     */
    @Column(name = "listed", insertable = false, updatable = false)
    private Long listed;

    /** The claim's status log, oldest first: a line for each status it has had, from its DRAFT on. */
    @OneToMany(cascade = CascadeType.ALL, fetch = FetchType.EAGER)
    @JoinColumn(name = "claim_id", nullable = false)
    @OrderBy("id ASC")
    private List<ClaimLogEntry> log = new ArrayList<>();

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.roundsOn = date;
        this.note = note;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    /** Defers the claim until the date, while the sheet's today is the made-on date. */
    public void setDeferredUntil(LocalDate deferredUntil, LocalDate madeOn) {
        this.deferredUntil = deferredUntil;
        this.deferredOn = madeOn;
    }

    /**
     * Whether the claim was deferred at the end of the day: OPEN then, deferred while the sheet's today was on or
     * before the day, until a date after it.
     */
    public boolean isDeferredAsOf(LocalDate day) {
        return statusAtEndOf(day) == ClaimStatus.OPEN && deferredUntil != null
                && (deferredOn == null || !deferredOn.isAfter(day)) && day.isBefore(deferredUntil);
    }

    /**
     * Whether the claim is deferred on the date: OPEN and deferred until a date after it. A deferred claim counts in
     * no total, is not overdue, cannot be settled and is left unbound by a statement; from its date on it is an OPEN
     * claim like any other.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public int getProofs() {
        return proofs;
    }

    /** Raises the claim's proofs count by one. */
    public void addProof() {
        proofs++;
    }

    public LocalDate getRoundsOn() {
        return roundsOn;
    }

    public void setRoundsOn(LocalDate roundsOn) {
        this.roundsOn = roundsOn;
    }

    /** Whether the claim is a correction: one with a negative amount. Its due has no floor and no late charge. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Moves the claim to another person of the sheet. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public Long getListed() {
        return listed;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public String getNumberSequence() {
        return numberSequence;
    }

    public Long getNumberInSequence() {
        return numberInSequence;
    }

    /** Numbers the claim in the sequence (a period's name, or X) at the place: the number shown is sequence-place. */
    public void numberIn(String sequence, long place) {
        this.number = sequence + "-" + place;
        this.numberSequence = sequence;
        this.numberInSequence = place;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    public boolean isStated() {
        return stated;
    }

    /**
     * Whether the claim's figure is bound by its person's last statement: stated, and not pending (a pending claim
     * shows its live figure; rejected, it is bound again).
     */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Binds the claim to the figure (null for n/a) until the next statement. */
    public void bind(BigDecimal figure) {
        this.stated = true;
        this.statedDue = figure;
    }

    /** Frees the claim: its due is live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }

    public List<ClaimLogEntry> getLog() {
        return log;
    }

    /**
     * The status the claim had at the end of the day, as its log records it: the last line logged on or before it (a
     * line with no date counts as before any day); null when the claim was added after it. A claim with no log has
     * its status now.
     */
    public ClaimStatus statusAtEndOf(LocalDate day) {
        if (log.isEmpty()) {
            return status;
        }
        ClaimStatus then = null;
        for (ClaimLogEntry e : log) {
            if (e.getOn() == null || !e.getOn().isAfter(day)) {
                then = e.getStatus();
            }
        }
        return then;
    }

    /**
     * The due its status log records at the end of the day: that of the last line logged on or before it; null when
     * there is none.
     */
    public BigDecimal dueLoggedAtEndOf(LocalDate day) {
        BigDecimal then = null;
        for (ClaimLogEntry e : log) {
            if (e.getOn() == null || !e.getOn().isAfter(day)) {
                then = e.getDue();
            }
        }
        return then;
    }

    /** The date its status log last records it SETTLED; null when it never was, or the line has no date. */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogEntry e : log) {
            if (e.getStatus() == ClaimStatus.SETTLED) {
                on = e.getOn();
            }
        }
        return on;
    }

    /** Logs the status the claim now has: by the user, on the sheet's today, at the due computed now. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogEntry(status, by, on, due));
    }
}
package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/**
 * A period of a sheet: a name unique on the sheet and a from and to date, inclusive. A closed period keeps the
 * due-total it had when it was closed, and each person's due-total for it then. A soft-closed period keeps them
 * the same way, but claims dated in it can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date", nullable = false)
    private LocalDate to;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this.sheetId = sheetId;
        this.name = name;
        this.from = from;
        this.to = to;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return Map.copyOf(closedPersonTotals);
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** Closes the period, fixing its due-total and each person's. */
    public void close(BigDecimal total, Map<Long, BigDecimal> personTotals) {
        fix(total, personTotals);
        this.closed = true;
        this.softClosed = false;
    }

    /** Soft-closes the period, fixing its due-total and each person's; claims dated in it can still change. */
    public void softClose(BigDecimal total, Map<Long, BigDecimal> personTotals) {
        fix(total, personTotals);
        this.softClosed = true;
    }

    private void fix(BigDecimal total, Map<Long, BigDecimal> personTotals) {
        this.closedTotal = total;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
    }

    /** Reopens the period, closed or soft-closed: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.sheet.TodayChanged;
import org.springframework.context.event.EventListener;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The periods of a sheet. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final ClaimService claimService;
    private final SettingsService settings;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetService sheets, ClaimRepository claims,
            PersonRepository people, ClaimService claimService, SettingsService settings, Audit audit) {
        this.settings = settings;
        this.periods = periods;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.claimService = claimService;
        this.audit = audit;
    }

    /** The sheet's periods, by from-date. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromAsc(sheetId);
    }

    /**
     * Adds a period; refused when its to-date is before its from-date, its name is in use on the sheet or its dates
     * overlap another period's.
     */
    @Transactional
    public Period add(String by, String sheetId, String name, LocalDate from, LocalDate to) {
        // the sheet stays locked until the transaction ends, so two periods added at once are checked in turn
        sheets.lock(sheetId);
        String trimmed = name.strip();
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts.");
        }
        if (periods.existsBySheetIdAndName(sheetId, trimmed)) {
            throw nameInUse();
        }
        if (periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, to, from)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
        }
        Period added;
        try {
            added = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
                + " from=" + added.getFrom() + " to=" + added.getTo());
        return added;
    }

    /**
     * Adds one period per calendar month from the from-date's month to the to-date's month, each from the first to the
     * last day of its month and named yyyy-mm, by month. A month whose name is in use on the sheet or whose days
     * overlap a period is left out; the others are still made. Refused when the to-date is before the from-date.
     */
    @Transactional
    public List<Period> generate(String by, String sheetId, LocalDate from, LocalDate to) {
        // the sheet stays locked until the transaction ends, so periods added at once are checked in turn
        sheets.lock(sheetId);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
        }
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (periods.existsBySheetIdAndName(sheetId, name)
                    || periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, last, first)) {
                continue;
            }
            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
                    + " from=" + added.getFrom() + " to=" + added.getTo());
            made.add(added);
        }
        return made;
    }

    /**
     * Closes the period, fixing each person's due-total for it now (the figures of their claims dated in it that
     * counted at the end of its last day, skipping n/a) and its own, the sum of those.
     * Refused unless the user's role may close, and when it is already closed.
     */
    @Transactional
    public Period close(String by, String sheetId, Long id) {
        // the sheet stays locked until the transaction ends, so no claim in the period changes while it closes
        LocalDate today = sheets.lock(sheetId).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessMay(sheetId, by, "close");
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        return close(by, sheetId, period, today, "");
    }

    /**
     * Soft-closes the period, fixing its figures as a close does while claims dated in it can still change. Refused
     * unless the user's role may close, and when it is already closed or soft-closed.
     */
    @Transactional
    public Period softClose(String by, String sheetId, Long id) {
        LocalDate today = sheets.lock(sheetId).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessMay(sheetId, by, "close");
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period, today);
        BigDecimal total = sum(personTotals);
        period.softClose(total, personTotals);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + by + " period=" + saved.getName()
                + " total=" + total.toPlainString());
        return saved;
    }

    /**
     * Once the sheet's today is changed while it has grace days, closes every open period (not soft-closed) whose to-date plus them is
     * before the new today, by to-date, each as a close by hand would.
     */
    @EventListener
    @Transactional
    public void autoClose(TodayChanged change) {
        Sheet sheet = change.sheet();
        Integer graceDays = sheet.getGraceDays();
        if (graceDays == null) {
            return;
        }
        LocalDate today = sheet.getToday();
        for (Period period : periods.findBySheetIdAndClosedFalseAndToBeforeOrderByToAsc(sheet.getId(),
                today.minusDays(graceDays))) {
            // a soft-closed period keeps the figures it fixed
            if (period.isSoftClosed()) {
                continue;
            }
            close(change.by(), sheet.getId(), period, today, " auto=yes");
        }
    }

    private Period close(String by, String sheetId, Period period, LocalDate today, String auditSuffix) {
        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period, today);
        BigDecimal total = sum(personTotals);
        period.close(total, personTotals);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + by + " period=" + saved.getName()
                + " total=" + total.toPlainString() + auditSuffix);
        return saved;
    }

    private static BigDecimal sum(Map<Long, BigDecimal> personTotals) {
        return personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * Each person's due-total for the period now: the figures of their claims dated in it that counted at the end of
     * its last day, skipping n/a; 0.00 for a person with none.
     */
    private Map<Long, BigDecimal> personTotals(String sheetId, Period period, LocalDate today) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        // every person on the sheet now gets a figure, 0.00 when none of their counted claims is dated in it
        Map<Long, BigDecimal> personTotals = new HashMap<>();
        for (Long personId : byId.keySet()) {
            personTotals.put(personId, BigDecimal.ZERO.setScale(2));
        }
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(c.getPersonId());
            if (person == null || !person.countsAtEndOf(c, period.getTo(), today) || !period.contains(c.getDate())) {
                continue;
            }
            BigDecimal figure = claimService.due(sheetId, person, c);
            if (figure != null) {
                personTotals.merge(person.getId(), figure, BigDecimal::add);
            }
        }
        return personTotals;
    }

    /**
     * Reopens a closed or soft-closed period, making its due-total live again. Refused unless the user's role may reopen (a steward by
     * the standing rule), or when the period is not closed.
     */
    @Transactional
    public Period reopen(String by, String sheetId, Long id) {
        sheets.lock(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessMay(sheetId, by, "reopen");
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + by + " period=" + saved.getName());
        return saved;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
    }
}

