401	     * A user whose role may reassign (a steward by the standing rule) moves a DRAFT, OPEN or PENDING claim to another person of the sheet. It keeps its number and date,
402	     * loses any figure a statement bound it to (it is live again until its new person's next statement), and is
403	     * listed as its new person's newest claim. Refused unless the user's role may reassign, for a settled or voided claim,
404	     * to the person it is already with, in a closed period, and when it is dated after the new person's retirement.
405	     */
406	    @Transactional
407	    public Claim reassign(String by, String sheetId, Long id, Long toPersonId) {
408	        settings.refuseUnlessMay(sheetId, by, "reassign");
409	        Claim claim = lockedClaim(sheetId, id);
410	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
411	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot move.");
412	        }
413	        if (claim.getPersonId().equals(toPersonId)) {
414	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's.");
415	        }
416	        Person from = person(sheetId, claim.getPersonId());
417	        Person to = person(sheetId, toPersonId);
418	        refuseAfterRetirement(to, claim.getDate());
419	        RollupService.Snapshot before = rollup.snapshot(sheetId);
420	        claim.setPersonId(to.getId());
421	        claim.unbind();
422	        Claim saved = claims.saveAndFlush(claim);
423	        claims.relist(saved.getId());
424	        audit.recordOnCommit(record("CLAIM_REASSIGNED", by, to, saved) + " from=" + from.getName() + " to="
425	                + to.getName());
426	        rollup.recordChanges(by, sheetId, before);
427	        return saved;
428	    }
429	
430	    /**
431	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement bound it
432	     * to stays bound; its period (and rounding, unless a correction) follows the new date. While the sheet numbers by
433	     * period and the new date is in another period's sequence, the claim takes that sequence's next number, and its
434	     * old number is never given again. Refused unless the user is a steward, for a claim that is not OPEN or PENDING,
435	     * for a claim or a new date in a closed period, and for a new date after the person's retirement.
436	     */
437	    @Transactional
438	    public Claim redate(String by, String sheetId, Long id, LocalDate date) {
439	        if (!settings.isSteward(sheetId, by)) {
440	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim.");
441	        }
442	        Claim claim = lockedClaim(sheetId, id);
443	        if (!claim.getStatus().isOpen()) {
444	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be re-dated.");
445	        }
446	        refuseInClosedPeriod(sheetId, date);
447	        Person person = person(sheetId, claim.getPersonId());
448	        refuseAfterRetirement(person, date);
449	        RollupService.Snapshot before = rollup.snapshot(sheetId);
450	        LocalDate old = claim.getDate();
451	        String oldSequence = sequenceOn(sheetId, old);
452	        claim.setDate(date);
453	        if (!claim.isCorrection()) {
454	            claim.setRoundsOn(date);
455	        }
456	        if (numbersByPeriod(sheetId) && !sequenceOn(sheetId, date).equals(oldSequence)) {
457	            if (claim.getNumberSequence() != null) {
458	                claims.retireNumber(sheetId, claim.getNumberSequence(), claim.getNumberInSequence());
459	            }
460	            number(sheetId, claim);
461	        }
462	        Claim saved = claims.saveAndFlush(claim);
463	        audit.recordOnCommit(record("CLAIM_REDATED", by, person, saved) + " old=" + old + " new=" + date);
464	        rollup.recordChanges(by, sheetId, before);
465	        return saved;
466	    }
467	
468	    /** An OPEN claim after a split, and the new OPEN claim split off it. */
469	    public record Split(Claim original, Claim split) {
470	    }
471	
472	    /**
473	     * Splits an amount (more than 0.00 and less than the claim's) off an OPEN claim: the claim keeps the rest and
474	     * loses any figure a statement bound it to; a new OPEN claim with the amount, the same date and note, the next
475	     * number, opened by the user, with a due-by from the terms in force on the date, and split from the original's
476	     * number, is listed as its person's newest. Refused unless the user's role may open a claim, for a claim that is
477	     * not OPEN or is deferred, for an amount out of range, and in a closed period.
478	     */
479	    @Transactional
480	    public Split split(String by, String sheetId, Long id, BigDecimal amount) {
481	        settings.refuseUnlessMay(sheetId, by, "open");
482	        Claim claim = lockedClaim(sheetId, id);
483	        if (claim.getStatus() != ClaimStatus.OPEN) {
484	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
485	        }
486	        if (claim.isDeferredOn(sheets.load(sheetId).getToday())) {
487	            throw new ResponseStatusException(HttpStatus.CONFLICT,
488	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
489	        }
490	        if (amount == null || amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
491	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
492	                    "The amount split off must be more than 0.00 and less than the claim's.");
493	        }
494	        RollupService.Snapshot before = rollup.snapshot(sheetId);
495	        Person person = person(sheetId, claim.getPersonId());
496	        claim.setAmount(claim.getAmount().subtract(scaled(amount)));
497	        claim.unbind();
498	        Claim original = claims.saveAndFlush(claim);
499	        Claim part = new Claim(sheetId, claim.getPersonId(), scaled(amount), claim.getDate(), claim.getNote());
500	        part.setRoundsOn(claim.getRoundsOn());
501	        part.setDueBy(claim.getDate().plusDays(termsFor(sheetId, person, claim.getDate())));
502	        part.setSplitFrom(claim.getNumber());
503	        part.setStatus(ClaimStatus.OPEN);
504	        number(sheetId, part);
505	        part.setOpenedBy(by);
506	        logStatus(by, sheetId, person, part);
507	        Claim added = claims.saveAndFlush(part);
508	        audit.recordOnCommit(record("CLAIM_SPLIT", by, person, original) + " into=" + added.getNumber());
509	        audit.recordOnCommit(record("CLAIM_OPENED", by, person, added));
510	        rollup.recordChanges(by, sheetId, before);
511	        return new Split(original, added);
512	    }
