514	    /**
515	     * Refuses voiding a SETTLED claim unless the user is a steward and the sheet's today is within
516	     * {@link #VOID_SETTLED_DAYS} days of the date its status log records it settled.
517	     */
518	    private void refuseVoidOfSettled(String by, String sheetId, Claim claim) {
519	        if (!settings.isSteward(sheetId, by)) {
520	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim.");
521	        }
522	        LocalDate settledOn = claim.settledOn();
523	        LocalDate today = sheets.load(sheetId).getToday();
524	        if (settledOn == null || today == null || today.isBefore(settledOn)
525	                || ChronoUnit.DAYS.between(settledOn, today) > VOID_SETTLED_DAYS) {
526	            throw new ResponseStatusException(HttpStatus.CONFLICT,
527	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
528	        }
529	    }
530	
531	    /** Logs the status the claim now has: by the user, on the sheet's today, at the due it shows now. */
532	    private void logStatus(String by, String sheetId, Person person, Claim claim) {
533	        claim.logStatus(by, sheets.load(sheetId).getToday(), due(sheetId, person, claim));
534	    }
535	
536	    /** The pending claim, locked, for a steward to decide; refused otherwise. */
537	    private Claim pendingClaim(String by, String sheetId, Long id) {
538	        Claim claim = lockedClaim(sheetId, id);
539	        if (claim.getStatus() != ClaimStatus.PENDING) {
540	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
541	        }
542	        if (!settings.isSteward(sheetId, by)) {
543	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim.");
544	        }
545	        return claim;
546	    }
547	
548	    /** The claim, locked; refused when it is dated in a closed period. */
549	    private Claim lockedClaim(String sheetId, Long id) {
550	        // the sheet is locked before the claim, in the order a period closing takes them
551	        sheets.lock(sheetId);
552	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
553	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
554	        refuseInClosedPeriod(sheetId, claim.getDate());
555	        return claim;
556	    }
557	
558	    /**
559	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
560	     * after it, the next in the sequence of the period the claim is dated in (X for none), else the sheet's next.
561	     * The sheet is locked, so two claims opened at once never get the same one.
562	     */
563	    private void number(String sheetId, Claim claim) {
564	        if (!numbersByPeriod(sheetId)) {
565	            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
566	            return;
567	        }
568	        String sequence = sequenceOn(sheetId, claim.getDate());
569	        Long last = claims.lastInSequence(sheetId, sequence);
570	        claim.numberIn(sequence, last == null ? 1 : last + 1);
571	    }
572	
573	    /** Whether the sheet numbers claims by period: its period numbering from is set and its today on or after it. */
574	    private boolean numbersByPeriod(String sheetId) {
575	        Sheet sheet = sheets.load(sheetId);
576	        LocalDate from = sheet.getPeriodNumberingFrom();
577	        return from != null && !sheet.getToday().isBefore(from);
578	    }
579	
580	    /** The number sequence of a claim dated on the date: the name of the period it is in, or X for none. */
581	    private String sequenceOn(String sheetId, LocalDate date) {
582	        return periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)
583	                .map(Period::getName).orElse(NO_PERIOD);
584	    }
585	
586	    /**
587	     * The claim's rate figure: at the rate its person's grade in force on its date has in force on that date, rounded
588	     * as the sheet's policy date decides for it, with no floor; null (n/a) with none.
589	     */
590	    public BigDecimal rateFigure(String sheetId, Person person, Claim claim) {
591	        Sheet sheet = sheets.load(sheetId);
592	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
593	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
594	                .map(pct -> dueOn(claim.getAmount(), pct, rounding)).orElse(null);
595	    }
596	
597	    /**
598	     * The figure of the claim: its settled due, else the one a statement bound it to (not while it is pending), else
599	     * its rate figure. A statement binds this figure, under the late charge and the floor.
600	     */
601	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
602	        if (claim.getSettledDue() != null) {
603	            return claim.getSettledDue();
604	        }
605	        return claim.isBound() ? claim.getStatedDue() : rateFigure(sheetId, person, claim);
606	    }
607	
608	    /**
609	     * The due the claim shows and totals: its settled due as frozen, else its live due on its figure (the late charge
610	     * only while it is open or pending).
611	     */
612	    public BigDecimal due(String sheetId, Person person, Claim claim) {
613	        BigDecimal figure = figure(sheetId, person, claim);
614	        return claim.getSettledDue() != null ? figure
615	                : liveDue(figure, claim, sheets.load(sheetId), claim.getStatus().isOpen());
616	    }
617	
618	    /**
619	     * The live due of a claim on its (unfloored) figure: the greater of the floor in force on its date and the figure
620	     * plus the late charge it has gained (when charged); a correction has neither floor nor charge. Null (n/a) for an
621	     * n/a figure.
622	     */
623	    public static BigDecimal liveDue(BigDecimal figure, Claim claim, Sheet sheet, boolean charged) {
624	        if (figure == null || claim.isCorrection()) {
625	            return figure;
626	        }
627	        BigDecimal due = charged ? withLateCharge(figure, claim, sheet) : figure;
628	        return sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
629	    }
630	
631	    /**
632	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
633	     * due-by) by the sheet's today: for each such boundary (its due-by plus 30, 60, 90 ... days), the sheet's late
634	     * percent in force on that boundary date of the figure, rounded like its due; a boundary whose percent is 0.00
635	     * adds nothing. A deferred claim is not overdue. The charge is never bound by a statement: it keeps following the
636	     * sheet's today and its policy date.
637	     */
638	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Sheet sheet) {
639	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
640	            return figure;
641	        }
642	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday());
643	        long periods = overdue > 0 ? overdue / 30 : 0;
644	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
645	        BigDecimal due = figure;
646	        for (long k = 1; k <= periods; k++) {
647	            BigDecimal latePct = sheet.latePctOn(claim.getDueBy().plusDays(30 * k));
648	            if (latePct.signum() != 0) {
649	                due = due.add(dueOn(figure, latePct, rounding));
650	            }
651	        }
652	        return due;
653	    }
654	
655	    /**
656	     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
657	     * the transaction ends, so a period closing at the same moment is checked in turn.
658	     */
659	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
660	        sheets.lock(sheetId);
661	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
662	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
663	        }
664	    }
665	
666	    /**
667	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
668	     * claim of the person, else refused; null for any other claim.
669	     */
670	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
671	        if (amount.signum() >= 0) {
672	            return null;
673	        }
674	        corrects = corrects == null ? null : corrects.strip();
675	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
676	                ClaimStatus.SETTLED)) {
677	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
678	                    "A negative amount must correct a settled claim of the person, named by its number.");
679	        }
680	        return corrects;
681	    }
682	
683	    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
684	    private static void refuseAfterRetirement(Person person, LocalDate date) {
685	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
686	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
687	                    "That claim is dated after the person's retirement.");
688	        }
689	    }
690	
691	    private Person person(String sheetId, Long personId) {
692	        return people.findByIdAndSheetId(personId, sheetId)
693	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
694	    }
695	
696	    /**
697	     * The terms a claim of the person dated on the date has: the person's own, else those of their grade on the date,
698	     * else the sheet's on the date.
699	     */
700	    private int termsFor(String sheetId, Person person, LocalDate on) {
701	        return person.getTerms() != null ? person.getTerms()
702	                : sheets.load(sheetId).termsFor(person.gradeOn(on), on);
703	    }
704	
705	    /** The audit line about a claim; one that has a number ends with it. */
706	    private static String record(String event, String by, Person person, Claim c) {
707	        String number = c.getNumber();
708	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
709	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
710	                + (number != null ? " number=" + number : "");
711	    }
712	
713	    /**
714	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
715	     * negative amount rounds like its positive).
716	     */
717	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
718	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
719	    }
720	
721	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
722	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
723	        return corrects == null ? on
724	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
725	    }
726	
727	    /** The due raised to the floor when it is below it. */
728	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
729	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
730	    }
731	
732	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
733	        return date != null ? date : sheets.load(sheetId).getToday();
734	    }
735	
736	    /** The date, or for none the sheet's entry date, or its today when that is blank. */
737	    private LocalDate dateOrEntryDate(String sheetId, LocalDate date) {
738	        if (date != null) {
739	            return date;
740	        }
741	        Sheet sheet = sheets.load(sheetId);
742	        return sheet.getEntryDate() != null ? sheet.getEntryDate() : sheet.getToday();
743	    }
744	
745	    private static String text(BigDecimal value) {
746	        return value == null ? "n/a" : value.toPlainString();
747	    }
748	
749	    private static BigDecimal scaled(BigDecimal amount) {
750	        return amount.setScale(2, RoundingMode.UNNECESSARY);
751	    }
752	
753	    private static String noteOf(String note) {
754	        return note == null ? "" : note.strip();
755	    }
756	}
