// The people who are active: with an open or pending counted claim dated within the 30 days up to today.
protected readonly activeIds = computed(() => {
  });
  // A today change releases every claim, so an open editor is closed with it.
  let today: string | null | undefined;
  effect(() => {
    const now = this.session.sheetToday();
